// Bangladesh outline from Natural Earth data (generated by
// `tools/build-map.mjs` into `js/data/map-bd.js`). Each MAINLAND vertex
// carries the type of the edge that STARTS at it:
//   I = border with India (enemies come from here)
//   M = border with Myanmar
//   C = coastline (Bay of Bengal)
// MAINLAND is clockwise from the northernmost vertex.
import { MAINLAND, ISLANDS as RAW_ISLANDS, INDIA_LAND as RAW_INDIA, OTHER_LAND as RAW_OTHER, MYANMAR_OUTLINE } from './data/map-bd.js';

// Equirectangular projection to "map units" (~1 unit ≈ 100 km). y grows downward.
const COS = Math.cos((24 * Math.PI) / 180);
export const proj = (lon, lat) => [(lon - 88) * COS, 26.8 - lat];

export const BD = MAINLAND.map(([lon, lat]) => proj(lon, lat));

// Projected island rings (Bhola, Hatiya, etc.). Drawing only: not part of
// BD, so spawns and breaches use the mainland polygon.
export const ISLANDS = RAW_ISLANDS.map((ring) => ring.map(([lon, lat]) => proj(lon, lat)));

// Projected neighbour land (drawn as background; INDIA also gates spawns).
export const INDIA = RAW_INDIA.map((ring) => ring.map(([lon, lat]) => proj(lon, lat)));
export const OTHER_LAND = RAW_OTHER.map((ring) => ring.map(([lon, lat]) => proj(lon, lat)));

export const INDIA_EDGES = [];
MAINLAND.forEach((v, i) => {
  if (v[2] !== 'I') return;
  const a = BD[i];
  const b = BD[(i + 1) % BD.length];
  INDIA_EDGES.push({ a, b, len: Math.hypot(b[0] - a[0], b[1] - a[1]) });
});
export const INDIA_LEN = INDIA_EDGES.reduce((s, e) => s + e.len, 0);

// Bay of Bengal: the C-tagged coastline (in MAINLAND order, from the
// Myanmar end at Teknaf west to the India end in the delta), then
// far-away points to the south-west, south and south-east so the polygon
// covers the bay without overlapping BD. The two share only the coastline
// itself; the closing edges stay south of BD, so SEA is simple. Kept for
// compatibility; the engine now fills the whole canvas with the sea
// gradient instead of using this polygon.
const coast = MAINLAND.filter((v) => v[2] === 'C');
// MAINLAND is clockwise from the north, so `coast` already runs Myanmar →
// India; this guards the sea polygon if the data order ever flips.
const coastOrdered =
  coast.length > 1 && coast[0][0] < coast[coast.length - 1][0] ? coast.slice().reverse() : coast;
export const SEA = [
  ...coastOrdered.map(([lon, lat]) => proj(lon, lat)),
  proj(89.10, 21.70),
  proj(80, 21.65),
  proj(80, 10),
  proj(93.5, 10),
  proj(92.95, 19.9),
];

// Western Myanmar (Rakhine/Chin) as a background shape. It shares the
// Bangladesh–Myanmar border with BD, so BD border vertices coincide with
// its edge; no BD interior point (e.g. Dhaka) lies inside it, so spawns
// are not rejected there.
export const MYANMAR = MYANMAR_OUTLINE.map(([lon, lat]) => proj(lon, lat));

export const DHAKA = proj(90.41, 23.81);

export const LABELS = [
  // `key` is looked up as `map.<key>` in js/i18n.js
  { key: 'india', at: proj(87.2, 25.0) },
  { key: 'india', at: proj(90.9, 26.25) },
  { key: 'india', at: proj(93.2, 24.6) },
  { key: 'myanmar', at: proj(93.4, 21.2) },
  { key: 'bay', at: proj(90.4, 21.0) },
];

export const BBOX = BD.reduce(
  (b, [x, y]) => ({
    minX: Math.min(b.minX, x), minY: Math.min(b.minY, y),
    maxX: Math.max(b.maxX, x), maxY: Math.max(b.maxY, y),
  }),
  { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity },
);

export function pointInPoly(poly, x, y) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i];
    const [xj, yj] = poly[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

export function distToPoly(poly, x, y) {
  let best = Infinity;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [ax, ay] = poly[j];
    const [bx, by] = poly[i];
    const dx = bx - ax, dy = by - ay;
    const t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / (dx * dx + dy * dy)));
    best = Math.min(best, Math.hypot(x - (ax + t * dx), y - (ay + t * dy)));
  }
  return best;
}
